package com.collabboard;
import com.collabboard.auth.*;import com.collabboard.dto.*;import com.collabboard.security.JwtService;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpServletResponse;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class AuthServiceTest {
 @Test void signupStoresOnlyBcryptHashAndSetsHttpOnlyCookie(){AppUserRepository users=mock(AppUserRepository.class);when(users.existsByEmailIgnoreCase("a@example.com")).thenReturn(false);when(users.save(any())).thenAnswer(i->i.getArgument(0));var service=new AuthService(users,new BCryptPasswordEncoder(4),new JwtService("test-secret-with-at-least-32-characters!!",86400000),false);var response=new MockHttpServletResponse();var result=service.signup(new SignUpRequest("Alex","a@example.com","very-secure-password","very-secure-password"),response);var user=users.findByEmailIgnoreCase("a@example.com");assertEquals("Alex",result.name());verify(users).save(argThat(u->u.getPasswordHash().startsWith("$2a$")&&!u.getPasswordHash().contains("very-secure-password")));assertNotNull(response.getCookie("COLLABBOARD_SESSION"));assertTrue(response.getCookie("COLLABBOARD_SESSION").isHttpOnly());}
 @Test void signupRejectsPasswordMismatch(){var users=mock(AppUserRepository.class);var svc=new AuthService(users,new BCryptPasswordEncoder(4),new JwtService("test-secret-with-at-least-32-characters!!",86400000),false);assertThrows(IllegalArgumentException.class,()->svc.signup(new SignUpRequest("Alex","a@example.com","very-secure-password","not-the-same"),new MockHttpServletResponse()));verify(users,never()).save(any());}
}
